import assert from 'node:assert/strict';
import {startSlideDemo} from './slide-lab.mjs';
const frame={ticks:2,obsel:3,tiles:[],parts:[],cgram:Buffer.alloc(512).toString('base64')};
const data={schema:'issd-slide-lab-local/v1',width:96,height:96,frames:Array.from({length:6},()=>({...frame}))};
const motion={schema:'issd-runtime-body-local/v1',cycles:{walking:[{height:52}]}},preview={schema:'issd-editor-preview-local/v1',teams:Array.from({length:36},()=>({palettes:[Array(16).fill(0),Array(16).fill(0)]}))};
const palette=Array(16).fill('#000000'),catalog={teams:Array.from({length:36},(_,id)=>({id,name:'Equipe '+id,kit:{home:{sprite_palette:palette},away:{sprite_palette:palette}}}))};
const resources={'preview.json':data,'left.json':data,'runtime-body-local.json':motion,'editor-preview-local.json':preview,'issd-rom-catalog.json':catalog};
const element=()=>({value:'',textContent:'',disabled:false,children:[],listeners:{},addEventListener(k,cb){this.listeners[k]=cb;},replaceChildren(...x){this.children=x;},fire(k){this.listeners[k]?.();}});
const els=Object.fromEntries(['team','kit','direction','skin','hair','demo','play','tick','frame','status'].map(k=>['slide-'+k,element()]));
els['slide-kit'].value='home';els['slide-direction'].value='2';els['slide-skin'].value='0';let draws=0;
els['slide-demo'].getContext=()=>({clearRect(){},drawImage(){draws++;}});
const doc={getElementById:id=>els[id],createElement:element};let scheduled;
const env={fetch:async path=>{const data=resources[path.split('/').pop()];return {ok:!!data,json:async()=>data};},requestFrame:cb=>{scheduled=cb;},makeCanvas:(w,h)=>({width:w,height:h,getContext:()=>({createImageData:()=>({data:new Uint8ClampedArray(w*h*4)}),putImageData(){}})})};
await startSlideDemo(doc,env);assert.equal(els['slide-team'].children.length,36);assert.equal(els['slide-hair'].children.length,14);assert.ok(draws>0);assert.match(els['slide-status'].textContent,/Corpo capturado/);
els['slide-team'].value='2';els['slide-kit'].value='away';els['slide-team'].fire('change');assert.match(els['slide-status'].textContent,/Corpo capturado/);
els['slide-direction'].value='6';els['slide-direction'].fire('change');assert.match(els['slide-status'].textContent,/Corpo capturado/);
els['slide-direction'].value='3';els['slide-direction'].fire('change');assert.match(els['slide-status'].textContent,/ainda não disponível/);
els['slide-direction'].value='2';els['slide-direction'].fire('change');els['slide-tick'].value='7';els['slide-tick'].fire('input');assert.equal(els['slide-frame'].textContent,'8 / 12');assert.equal(els['slide-play'].textContent,'Reproduzir');
els['slide-play'].fire('click');scheduled(100);scheduled(150);assert.equal(els['slide-frame'].textContent,'11 / 12');
console.log('OK: laboratório permite selecionar equipe, uniforme e inspecionar o carrinho');
